def text_of(raw: bytes) -> Result[str, str]:
    return raw.decode()

def main() -> int:
    encoded = "h\u00e9llo".encode()
    if len(encoded) != 6:
        return 1
    match text_of(encoded):
        case Ok(value):
            if value != "h\u00e9llo":
                return 2
        case Err(message):
            return 0 - len(message)
    match text_of(b"\xff"):
        case Ok(other):
            return 0 - len(other)
        case Err(message):
            return len(encoded)

