def parse(digits: str) -> Result[bytes, str]:
    return bytes.fromhex(digits)

def main() -> int:
    raw = b"\x0f\xa0"
    if raw.hex() != "0fa0":
        return 1
    if len(b"".hex()) != 0:
        return 2
    match parse("0fa0"):
        case Ok(value):
            if value != raw:
                return 3
        case Err(message):
            return 0 - len(message)
    match parse("0f0"):
        case Ok(value):
            return 0 - len(value)
        case Err(message):
            return len(message)

